export type TranslationKey = keyof typeof messages["zh-CN"];
export const useI18n = () => {
  const languageStore = useLanguageStore();
  const locale = computed(() => languageStore.locale);
  const languageLabel = computed(() => (locale.value === "zh-CN" ? "EN" : "中"));
  const t = (key: TranslationKey): string => messages[locale.value][key] ?? messages["zh-CN"][key] ?? key;
  const setLocale = (nextLocale: Locale): void => languageStore.setLocale(nextLocale);
  const toggleLocale = (): void => languageStore.toggleLocale();
  watch(locale, (nextLocale) => { if (typeof document !== "undefined") document.documentElement.lang = nextLocale; }, { immediate: true });
  return { locale, languageLabel, t, setLocale, toggleLocale };
};
